#!/bin/sh
# Installer for the touchbar-statusline variant — Hammerspoon host (native Apple Silicon).
#
# Unlike MTMR (Intel-only, needs Rosetta), this path is fully native arm64: Hammerspoon ships a
# native cask, and the experimental Touch Bar module is a universal (x86_64+arm64) binary. The
# Claude status-line script writes a cache on each render; a Hammerspoon Lua config paints it
# into the Touch Bar's system tray.
#
#   curl -fsSL .../variants/install-touchbar-hammerspoon.sh | sh
#
set -e

case "$(uname -s)" in
  Darwin) ;;
  *) echo "Error: the Touch Bar variant is macOS-only." >&2; exit 1 ;;
esac

CLAUDE_DIR="$HOME/.claude"
TB_DIR="$CLAUDE_DIR/touchbar"
HS_DIR="$HOME/.hammerspoon"
mkdir -p "$TB_DIR" "$HS_DIR"

# Optional GPS: install CoreLocationCLI for precise weather location (matches the repo's variants).
# Without it (or without WITH_GPS=1), weather geolocates by IP via wttr.in.
if [ "${WITH_GPS:-0}" = "1" ]; then
  if command -v CoreLocationCLI >/dev/null 2>&1 || command -v whereami >/dev/null 2>&1; then
    echo "GPS helper already installed; skipping."
  elif command -v brew >/dev/null 2>&1; then
    echo "Installing CoreLocationCLI (first weather fetch triggers a Location Services prompt)..."
    brew install corelocationcli || echo "WARN: corelocationcli install failed; weather will use IP."
  else
    echo "WARN: WITH_GPS=1 set but Homebrew not found; weather will use IP geolocation."
  fi
fi

# Universal (x86_64+arm64) precompiled Touch Bar module — loads natively on Apple Silicon.
MODULE_URL="https://raw.githubusercontent.com/asmagill/hs._asm.undocumented.touchbar/master/touchbar-v0.8.3.2alpha-universal.tar.gz"

# --- 1. Ensure Hammerspoon is installed (native arm64) --------------------------------------
if [ ! -d "/Applications/Hammerspoon.app" ]; then
  if command -v brew >/dev/null 2>&1; then
    echo "Installing Hammerspoon (native Apple Silicon) via Homebrew..."
    brew install --cask hammerspoon || {
      echo "WARN: 'brew install --cask hammerspoon' failed."
      echo "      Install it from https://www.hammerspoon.org and re-run this script."
    }
  else
    echo "WARN: Homebrew not found. Install Hammerspoon from https://www.hammerspoon.org, then re-run."
  fi
else
  echo "Hammerspoon already installed."
fi

# --- 2. Install the universal Touch Bar module under ~/.hammerspoon -------------------------
if [ ! -f "$HS_DIR/hs/_asm/undocumented/touchbar/internal.so" ]; then
  echo "Installing the Touch Bar module (universal binary)..."
  tmp_tgz=$(mktemp -t tbmod).tar.gz
  if curl -fsSL "$MODULE_URL" -o "$tmp_tgz"; then
    tar -xzf "$tmp_tgz" -C "$HS_DIR"
    rm -f "$tmp_tgz"
    if [ -f "$HS_DIR/hs/_asm/undocumented/touchbar/internal.so" ]; then
      echo "  Touch Bar module installed ($(lipo -archs "$HS_DIR/hs/_asm/undocumented/touchbar/internal.so" 2>/dev/null))."
    else
      echo "  WARN: extraction did not produce the expected module files."
    fi
  else
    echo "  WARN: could not download the Touch Bar module from $MODULE_URL"
  fi
else
  echo "Touch Bar module already present."
fi

# --- 3. Write the status-line cache writer -------------------------------------------------
printf %s '' \
  | base64 -d > "$CLAUDE_DIR/touchbar-statusline.sh"
chmod +x "$CLAUDE_DIR/touchbar-statusline.sh"

# --- 4. Write the Hammerspoon Lua module ----------------------------------------------------
printf %s '' \
  | base64 -d > "$HS_DIR/claude_touchbar.lua"

# --- 5. Ensure init.lua loads the module ----------------------------------------------------
INIT="$HS_DIR/init.lua"
if [ -f "$INIT" ]; then
  cp "$INIT" "$INIT.bak-$(date +%Y%m%d%H%M%S)"
fi
if ! grep -q 'claude_touchbar' "$INIT" 2>/dev/null; then
  printf '\nrequire("claude_touchbar")\n' >> "$INIT"
fi

# --- 6. Wire up settings.json ---------------------------------------------------------------
SETTINGS="$CLAUDE_DIR/settings.json"
[ -f "$SETTINGS" ] || echo "{}" > "$SETTINGS"
CMD="sh $CLAUDE_DIR/touchbar-statusline.sh"
if command -v jq >/dev/null 2>&1; then
  tmp=$(mktemp)
  jq --arg cmd "$CMD" '.statusLine = {type:"command", command:$cmd}' "$SETTINGS" > "$tmp" && mv "$tmp" "$SETTINGS"
else
  python3 - "$SETTINGS" "$CMD" <<'PY'
import json, sys
path, cmd = sys.argv[1], sys.argv[2]
try:
    d = json.load(open(path))
except Exception:
    d = {}
d["statusLine"] = {"type": "command", "command": cmd}
json.dump(d, open(path, "w"), indent=2)
PY
fi

# --- 7. (Re)launch Hammerspoon so it loads the config ---------------------------------------
if [ -d "/Applications/Hammerspoon.app" ]; then
  pkill -x Hammerspoon 2>/dev/null || true
  open -a Hammerspoon 2>/dev/null || true
fi

cat <<'EOF'

touchbar-statusline (Hammerspoon host) installed — fully native, no Rosetta.

Next steps:
  1. Grant Hammerspoon Accessibility permission when prompted:
     System Settings → Privacy & Security → Accessibility → enable Hammerspoon.
     (Then in Hammerspoon's menu, Reload Config, or just relaunch the app.)
  2. Restart Claude Code so it picks up the new status line.
  3. Tap the "⌁" button in the Touch Bar control strip (right side) to open the bar:
     ⌁ model · ctx% · 5h · 7d · cost · cpu/ram/bat, color-coded, refreshing ~2s.
     Tap ✕ to close it — the Touch Bar goes back to your other apps/tools and the ⌁
     button stays in the control strip to reopen it anytime.
     When idle (no render for 90s) the Claude metrics dim to "idle".

Notes:
  - This module is experimental and uses undocumented APIs. If the item doesn't appear,
    open Hammerspoon's Console (menu bar icon) and check for "[claude_touchbar]" messages.
  - Tune width: edit WIDTH in ~/.hammerspoon/claude_touchbar.lua, then Reload Config.

Uninstall:
  - Remove the require("claude_touchbar") line from ~/.hammerspoon/init.lua (or restore init.lua.bak-*).
  - Point .statusLine in ~/.claude/settings.json back to your previous command.
EOF
